import math

def is_pretty(m, n, alpha, k):
    if m <= 0 or n <= 0:
        return False
    return m * math.ceil(n * alpha) - n * math.floor(m * alpha) == k

def is_cool(m, n, alpha, k):
    if not is_pretty(m, n, alpha, k):
        return False

    # Check (m-n, n)
    m_minus_n, n_prime = m - n, n
    if m_minus_n <= 0:
        is_pn_pretty = False
    else:
        is_pn_pretty = is_pretty(m_minus_n, n_prime, alpha, k)

    if is_pn_pretty:
        return False

    # Check (m, n-m)
    m_prime, n_minus_m = m, n - m
    if n_minus_m <= 0:
        is_pm_pretty = False
    else:
        is_pm_pretty = is_pretty(m_prime, n_minus_m, alpha, k)

    if is_pm_pretty:
        return False

    return True

# Test for k=1 using alpha = sqrt(2)
alpha_val = math.sqrt(2)
k_val = 1
cool_pairs_k1 = []
max_m = 10
max_n = 10

for m in range(1, max_m + 1):
    for n in range(1, max_n + 1):
        if is_cool(m, n, alpha_val, k_val):
            cool_pairs_k1.append((m, n))

print(f"Cool pairs for k=1 (up to 10x10): {cool_pairs_k1}")
print(f"Count for k=1: {len(cool_pairs_k1)}")
